1	"use client"
2	
3	import { useEffect } from "react"
4	
5	const CSS = `
6	@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+KR:wght@400;500;600;700;900&family=Noto+Sans+KR:wght@300;400;500;700&display=swap');
7	:root{
8	  --bg:#0b0a09; --bg2:#100f0d; --ink:#f3efe6; --muted:#8d877b; --muted2:#5d584f;
9	  --gold:#c9a24b; --goldsoft:rgba(201,162,75,.32); --line:rgba(201,162,75,.16);
10	  --serif:"Noto Serif KR",Georgia,serif; --sans:"Noto Sans KR","Pretendard",sans-serif;
11	}
12	*{box-sizing:border-box;margin:0;padding:0;}
13	html{scroll-behavior:smooth;}
14	body{background:
15	    radial-gradient(ellipse 80% 50% at 50% -10%,rgba(201,162,75,.06),transparent 60%),
16	    radial-gradient(ellipse 60% 40% at 100% 100%,rgba(201,162,75,.04),transparent 55%),
17	    var(--bg);
18	  color:var(--ink);font-family:var(--sans);font-weight:300;-webkit-font-smoothing:antialiased;line-height:1.7;letter-spacing:.2px;}
19	.wrap{max-width:1180px;margin:0 auto;padding:0 40px;}
20	.ser{font-family:var(--serif);}
21	.gold{color:var(--gold);}
22	.eyebrow{font-size:11px;font-weight:500;letter-spacing:6px;color:var(--gold);text-transform:uppercase;}
23	.rule{width:46px;height:1px;background:var(--gold);margin:26px auto;}
24	a{color:inherit;text-decoration:none;}
25	
26	/* nav */
27	.nav{position:fixed;top:0;left:0;right:0;z-index:60;background:rgba(11,10,9,.97);border-bottom:1px solid var(--line);}
28	.nav .inner{display:flex;align-items:center;justify-content:space-between;height:72px;max-width:1180px;margin:0 auto;padding:0 40px;}
29	.brand{font-family:var(--serif);font-weight:700;font-size:20px;letter-spacing:4px;}
30	.nav nav{display:flex;gap:34px;font-size:12px;letter-spacing:2px;color:var(--muted);text-transform:uppercase;}
31	.nav nav a:hover{color:var(--ink);}
32	.hamburger{display:none;flex-direction:column;gap:5px;cursor:pointer;background:none;border:none;padding:6px;}
33	.hamburger span{width:22px;height:2px;background:var(--ink);border-radius:2px;display:block;transition:.3s;}
34	.hamburger.open span:nth-child(1){transform:rotate(45deg) translate(5px,5px);}
35	.hamburger.open span:nth-child(2){opacity:0;transform:scaleX(0);}
36	.hamburger.open span:nth-child(3){transform:rotate(-45deg) translate(5px,-5px);}
37	.mobnav{display:none;position:fixed;top:72px;left:0;right:0;z-index:59;background:rgba(11,10,9,.98);border-bottom:1px solid var(--line);flex-direction:column;padding:8px 0;}
38	.mobnav.open{display:flex;}
39	.mobnav a{font-size:12px;letter-spacing:3px;color:var(--muted);text-transform:uppercase;padding:16px 24px;border-bottom:1px solid var(--line);}
40	.mobnav a:last-child{border-bottom:none;}
41	.mobnav a:hover{color:var(--ink);}
42	@media(max-width:880px){.nav nav{display:none;}.hamburger{display:flex;}}
43	@media(max-width:480px){.nav .inner{height:60px;padding:0 18px;}.mobnav{top:60px;}}
44	
45	/* hero */
46	.hero{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;
47	  background:radial-gradient(ellipse at 50% 18%,rgba(201,162,75,.08),transparent 55%);padding:120px 24px;position:relative;}
48	.hero .eyebrow{margin-bottom:36px;}
49	.hero h1{font-family:var(--serif);font-weight:500;font-size:96px;line-height:1.04;letter-spacing:-2px;}
50	.hero h1 b{font-weight:900;}
51	.hero .lede{color:var(--muted);font-size:17px;letter-spacing:3px;margin-top:38px;font-weight:300;}
52	.hero .scroll{position:absolute;bottom:38px;color:var(--muted2);font-size:11px;letter-spacing:3px;}
53	@media(max-width:760px){.hero h1{font-size:52px;}}
54	
55	/* buttons (gold) */
56	.btn{display:inline-block;font-size:13px;letter-spacing:3px;text-transform:uppercase;color:var(--gold);border:1px solid var(--gold);padding:18px 40px;border-radius:2px;transition:.2s;margin:0 6px;background:transparent;cursor:pointer;}
57	.btn:hover{background:var(--gold);color:#0b0a09;}
58	.btn.sm{padding:12px 26px;font-size:11px;letter-spacing:2px;}
59	.btnrow{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-top:46px;}
60	@media(max-width:760px){.btn{padding:15px 24px;font-size:12px;letter-spacing:2px;}}
61	
62	/* sections */
63	section{padding:160px 0;}
64	.center{text-align:center;}
65	.kicker{font-size:11px;letter-spacing:5px;color:var(--gold);text-transform:uppercase;}
66	.display{font-family:var(--serif);font-weight:500;font-size:52px;line-height:1.25;letter-spacing:-1px;margin-top:24px;}
67	.display b{font-weight:900;}
68	.sub{color:var(--muted);font-size:16px;font-weight:300;margin-top:26px;max-width:620px;margin-left:auto;margin-right:auto;}
69	@media(max-width:760px){.display{font-size:34px;}section{padding:100px 0;}}
70	
71	/* manifesto */
72	.manifesto{border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--bg2);}
73	.manifesto .display{font-size:46px;}
74	.manifesto .mut{color:var(--muted2);}
75	
76	/* collection (pillars) */
77	.coll{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin-top:80px;border-top:1px solid var(--line);}
78	@media(max-width:820px){.coll{grid-template-columns:1fr;}}
79	.col{padding:54px 38px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);position:relative;}
80	.col:last-child{border-right:none;}
81	.col .no{font-family:var(--serif);font-size:14px;letter-spacing:3px;color:var(--gold);}
82	.col h3{font-family:var(--serif);font-weight:600;font-size:26px;margin:22px 0 14px;letter-spacing:-.5px;}
83	.col p{color:var(--muted);font-size:14px;font-weight:300;}
84	.detail{position:absolute;top:20px;right:20px;font-size:10px;letter-spacing:2px;color:var(--gold);border:1px solid var(--goldsoft);padding:6px 12px;border-radius:2px;cursor:pointer;text-transform:uppercase;transition:.2s;}
85	.detail:hover{background:var(--gold);color:#0b0a09;}
86	
87	/* teacher editorial */
88	.ed{display:grid;grid-template-columns:1fr 1fr;gap:0;align-items:stretch;border-top:1px solid var(--line);border-bottom:1px solid var(--line);}
89	@media(max-width:820px){.ed{grid-template-columns:1fr;}}
90	.ed .img{min-height:560px;background:linear-gradient(160deg,#1a1916,#0c0b09);display:flex;align-items:center;justify-content:center;color:var(--muted2);font-size:12px;letter-spacing:2px;border-right:1px solid var(--line);position:relative;overflow:hidden;}
91	.ed .img::after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 70% 20%,rgba(201,162,75,.10),transparent 60%);}
92	.ed .txt{padding:80px 64px;display:flex;flex-direction:column;justify-content:center;}
93	@media(max-width:820px){.ed .txt{padding:56px 32px;}.ed .img{min-height:380px;border-right:none;border-bottom:1px solid var(--line);}}
94	.ed h2{font-family:var(--serif);font-weight:500;font-size:38px;line-height:1.3;letter-spacing:-1px;margin:20px 0 30px;}
95	.ed ul{list-style:none;display:flex;flex-direction:column;gap:16px;}
96	.ed li{font-size:16px;color:var(--ink);padding-left:26px;position:relative;font-weight:300;}
97	.ed li::before{content:"";position:absolute;left:0;top:11px;width:14px;height:1px;background:var(--gold);}
98	.ed .note{color:var(--muted2);font-size:13px;margin-top:34px;letter-spacing:.5px;}
99	
100	/* system list */
101	.sys{background:var(--bg2);}
102	.syslist{max-width:760px;margin:70px auto 0;}
103	.sysrow{display:flex;align-items:baseline;gap:30px;padding:26px 0;border-top:1px solid var(--line);}
104	.sysrow .k{font-family:var(--serif);font-size:13px;letter-spacing:3px;color:var(--gold);width:140px;flex-shrink:0;}
105	.sysrow .t{font-size:19px;font-weight:300;}
106	@media(max-width:620px){.sysrow{flex-direction:column;gap:6px;}.sysrow .k{width:auto;}}
107	.sysdetail{max-width:760px;margin:30px auto 0;text-align:right;}
108	.detailline{display:inline-block;font-size:11px;letter-spacing:2px;color:var(--gold);border:1px solid var(--goldsoft);padding:10px 18px;border-radius:2px;cursor:pointer;text-transform:uppercase;transition:.2s;}
109	.detailline:hover{background:var(--gold);color:#0b0a09;}
110	
111	/* numbers */
112	.nums{display:grid;grid-template-columns:repeat(4,1fr);margin-top:80px;border-top:1px solid var(--line);border-left:1px solid var(--line);}
113	@media(max-width:760px){.nums{grid-template-columns:repeat(2,1fr);}}
114	.num{padding:50px 16px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);text-align:center;}
115	.num .v{font-family:var(--serif);font-size:52px;font-weight:600;color:var(--gold);letter-spacing:-1px;}
116	.num .l{color:var(--muted);font-size:12px;letter-spacing:2px;margin-top:12px;}
117	
118	/* proof : reviews + sample */
119	.revwrap{display:grid;grid-template-columns:1fr 1fr;gap:46px;margin-top:74px;text-align:left;align-items:start;}
120	@media(max-width:880px){.revwrap{grid-template-columns:1fr;gap:60px;}}
121	.revhead{font-family:var(--serif);font-size:22px;font-weight:600;margin-bottom:6px;}
122	.revsubt{color:var(--muted);font-size:13px;letter-spacing:1px;margin-bottom:22px;}
123	.slider{position:relative;max-width:360px;margin:0 auto;}
124	.slider .track .sl{display:none;}
125	.slider .track .sl.active{display:block;}
126	.slider .track iframe{width:100%;height:740px;border:1px solid var(--line);border-radius:10px;background:#000;display:block;}
127	.slider .track img{width:100%;height:auto;border:1px solid var(--line);border-radius:10px;background:#ffffff10;display:block;}
128	.sarrow{position:absolute;top:50%;transform:translateY(-50%);width:38px;height:38px;border-radius:50%;background:rgba(201,162,75,.92);color:#0b0a09;font-size:19px;border:none;display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:2;}
129	.sarrow.prev{left:-8px;}.sarrow.next{right:-8px;}
130	@media(max-width:480px){.sarrow.prev{left:2px;}.sarrow.next{right:2px;}}
131	.sdots{display:flex;gap:6px;justify-content:center;margin-top:16px;flex-wrap:wrap;}
132	.sdots .dot{width:7px;height:7px;border-radius:50%;background:var(--muted2);cursor:pointer;}
133	.sdots .dot.on{background:var(--gold);}
134	.slider.photo{overflow:hidden;}
135	.slider.photo .track{display:flex;transition:transform .38s cubic-bezier(.4,0,.2,1);}
136	.slider.photo .track .sl{flex-shrink:0;width:100%;display:block;}
137	.vid{max-width:780px;margin:70px auto 0;aspect-ratio:16/9;}
138	.vid iframe{width:100%;height:100%;border:1px solid var(--line);border-radius:10px;background:#000;}
139	.vidlbl{text-align:center;margin-top:70px;}
140	.vidlbl .revhead{font-size:24px;}
141	
142	/* review preview + modal */
143	.revpreview{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;cursor:pointer;position:relative;border-radius:4px;overflow:hidden;}
144	.revpreview img{width:100%;aspect-ratio:4/5;object-fit:cover;border:1px solid var(--line);}
145	.revbadge{position:absolute;inset:0;background:rgba(11,10,9,.42);display:flex;align-items:center;justify-content:center;font-size:11px;letter-spacing:3px;color:var(--gold);text-transform:uppercase;transition:.2s;}
146	.revpreview:hover .revbadge{background:rgba(11,10,9,.65);}
147	.rev3pg{display:none;grid-template-columns:repeat(3,1fr);gap:10px;}
148	.rev3pg.active{display:grid;}
149	.rev3pg img{width:100%;border-radius:4px;object-fit:contain;max-height:56vh;background:#0c0b09;}
150	.revnav{display:flex;align-items:center;justify-content:center;gap:20px;margin-top:18px;}
151	.revnav .arrow{position:static;transform:none;}
152	
153	/* materials */
154	.mats{display:grid;grid-template-columns:1fr 1fr;gap:1px;margin-top:34px;background:var(--line);border:1px solid var(--line);}
155	@media(max-width:760px){.mats{grid-template-columns:1fr;}}
156	.mat{background:var(--bg);padding:0;}
157	.mat .thumb{aspect-ratio:16/10;background:linear-gradient(160deg,#1a1916,#0c0b09);display:flex;align-items:center;justify-content:center;color:var(--muted2);font-size:12px;letter-spacing:2px;overflow:hidden;}
158	.mat .thumb img{width:100%;height:100%;object-fit:cover;}
159	.mat .body{padding:34px 36px;}
160	.mat h4{font-family:var(--serif);font-size:21px;font-weight:600;}
161	.mat p{color:var(--muted);font-size:14px;margin:10px 0 22px;font-weight:300;}
162	.lnk{font-size:12px;letter-spacing:3px;color:var(--gold);text-transform:uppercase;border-bottom:1px solid var(--goldsoft);padding-bottom:4px;}
163	.matlbl{margin-top:80px;text-align:center;}
164	
165	/* cta */
166	.cta{text-align:center;border-top:1px solid var(--line);}
167	
168	footer{border-top:1px solid var(--line);padding:56px 0;color:var(--muted2);font-size:12px;letter-spacing:1px;}
169	footer .top{display:flex;justify-content:space-between;flex-wrap:wrap;gap:18px;align-items:center;}
170	footer a{color:var(--gold);}
171	.photonote{font-size:10px;letter-spacing:2px;color:var(--muted2);margin-top:14px;text-transform:uppercase;}
172	
173	/* modal / slideshow */
174	.modal{position:fixed;inset:0;z-index:200;display:none;align-items:center;justify-content:center;background:rgba(5,5,4,.9);backdrop-filter:blur(4px);padding:28px;}
175	.modal.open{display:flex;}
176	.mbox{max-width:900px;width:100%;max-height:90vh;display:flex;flex-direction:column;background:var(--bg2);border:1px solid var(--line);border-radius:6px;overflow:hidden;}
177	.mhead{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;border-bottom:1px solid var(--line);}
178	.mhead .mt{font-family:var(--serif);font-size:16px;letter-spacing:1px;color:var(--gold);}
179	.mclose{font-size:20px;color:var(--muted);cursor:pointer;line-height:1;padding:4px 8px;border:1px solid var(--line);border-radius:3px;}
180	.mclose:hover{color:var(--ink);}
181	.mbody{padding:22px;overflow:auto;position:relative;}
182	.scrollhint{position:sticky;bottom:0;left:0;right:0;height:64px;background:linear-gradient(transparent,var(--bg2));display:flex;align-items:flex-end;justify-content:center;padding-bottom:10px;pointer-events:none;transition:opacity .3s;}
183	.scrollhint.hidden{opacity:0;}
184	@keyframes bounce{0%,100%{transform:translateY(0);}50%{transform:translateY(5px);}}
185	.scrollhint span{color:var(--gold);font-size:18px;animation:bounce 1.2s ease-in-out infinite;}
186	.stage{position:relative;display:flex;align-items:center;justify-content:center;background:#0c0b09;border-radius:4px;min-height:300px;}
187	.slide{display:none;max-width:100%;max-height:66vh;object-fit:contain;border-radius:4px;}
188	.slide.active{display:block;}
189	.arrow{position:absolute;top:50%;transform:translateY(-50%);width:42px;height:42px;border-radius:50%;background:rgba(201,162,75,.9);color:#0b0a09;font-size:20px;display:flex;align-items:center;justify-content:center;cursor:pointer;border:none;}
190	.arrow.prev{left:12px;}.arrow.next{right:12px;}
191	.mcap{text-align:center;color:var(--muted);font-size:13px;letter-spacing:1px;margin-top:16px;min-height:18px;}
192	.dots{display:flex;gap:7px;justify-content:center;margin-top:16px;flex-wrap:wrap;}
193	.dot{width:8px;height:8px;border-radius:50%;background:var(--muted2);cursor:pointer;}
194	.dot.on{background:var(--gold);}
195	.curvid{aspect-ratio:16/9;width:100%;margin-bottom:18px;}
196	.curvid iframe{width:100%;height:100%;border:0;border-radius:4px;}
197	.curimg{width:100%;border-radius:4px;display:block;}
198	.curcap{text-align:center;color:var(--muted);font-size:12px;letter-spacing:3px;text-transform:uppercase;margin:18px 0 8px;}
199	
200	.mob{display:none;}
201	@media(max-width:760px){.mob{display:inline;}}
202	@media(max-width:760px){
203	  .hero h1{font-size:72px;}
204	  .hero .eyebrow{font-size:13px;letter-spacing:5px;}
205	  .hero .lede{font-size:18px;letter-spacing:2px;}
206	}
207	@media(max-width:480px){
208	  .wrap{padding:0 18px;}
209	  .brand{font-size:16px;letter-spacing:2px;}
210	  .loginlink{padding:7px 12px;font-size:11px;letter-spacing:1px;}
211	  .hero h1{font-size:56px;}
212	  .hero .lede{font-size:16px;letter-spacing:2px;margin-top:24px;}
213	  .manifesto .display{font-size:26px;line-height:1.4;}
214	  .col{padding:36px 20px;}
215	  .ed h2{font-size:26px;}
216	  .ed .txt{padding:44px 20px;}
217	  .ed .img{min-height:300px;}
218	  .num{padding:30px 8px;}.num .v{font-size:34px;}
219	  .slider .track iframe{height:400px;}
220	  .mat .body{padding:20px 18px;}
221	  .matlbl{margin-top:50px;}
222	  .modal{padding:8px;}
223	  .mbox{max-height:96vh;}
224	  .mhead{padding:12px 16px;}
225	  .mbody{padding:12px;}
226	  .rev3pg{grid-template-columns:1fr;}
227	  .rev3pg img{max-height:70vh;}
228	  .revnav{gap:10px;}
229	  .display{font-size:28px;}
230	  section{padding:80px 0;}
231	  .btnrow{flex-wrap:nowrap;gap:8px;}
232	  .btn.sm{padding:11px 12px;font-size:11px;letter-spacing:1px;}
233	}
234	`
235	
236	const BODY = `
237	  <div class="nav"><div class="inner">
238	    <div class="brand">체계 국어</div>
239	    <nav><a href="#diff">PHILOSOPHY</a><a href="#teacher">신기태</a><a href="#proof">후기·자료</a><a href="#contact">문의</a></nav>
240	    <button class="hamburger" id="hamburger" onclick="toggleNav()" aria-label="메뉴"><span></span><span></span><span></span></button>
241	  </div></div>
242	  <div class="mobnav" id="mobnav">
243	    <a href="#diff" onclick="closeNav()">PHILOSOPHY</a>
244	    <a href="#teacher" onclick="closeNav()">신기태</a>
245	    <a href="#proof" onclick="closeNav()">후기·자료</a>
246	    <a href="#contact" onclick="closeNav()">문의</a>
247	  </div>
248	
249	  <div class="hero">
250	    <div class="eyebrow">전국 압도적 1위 시스템.</div>
251	    <h1 class="ser"><span style="display:inline-block;font-size:.42em;font-weight:400;color:var(--muted);letter-spacing:1px;margin-bottom:6px;">밑바닥에서</span><br/><b>압도적 역전</b></h1>
252	    <div class="lede">국어, 결국 제 수업입니다.</div>
253	  </div>
254	
255	  <section class="manifesto center"><div class="wrap">
256	    <div class="rule"></div>
257	    <div class="display ser"><span style="color:var(--muted2);">쓰레기 주입 수업은 그만.</span><br/>하게 만들고, <b class="gold">과정을 고치니까.</b></div>
258	    <div class="btnrow" style="margin-top:40px;">
259	      <a class="btn sm" href="https://naver.me/GMPANEIj" target="_blank" rel="noopener">수업 신청</a>
260	      <a class="btn sm" href="https://pf.kakao.com/_PHxexkn/chat" target="_blank" rel="noopener">상담 신청</a>
261	    </div>
262	  </div></section>
263	
264	  <section id="diff" class="center"><div class="wrap">
265	    <div class="kicker">The Difference</div>
266	    <div class="display ser">왜 압도적인가?</div>
267	    <div class="sub">이보다 좋은 학원이 있다면, <b class="gold">은퇴하겠습니다.</b></div>
268	    <div class="coll" style="text-align:left;">
269	      <div class="col">
270	        <span class="detail" onclick="openM('curModal')">상세보기</span>
271	        <div class="no">Ⅰ</div><h3>압도적 커리큘럼</h3><p>이해가 안될 때 어떻게 할건가요?<br/>변수 대처 — 실전적 관점.<br/>본질적 수업과 교재.<br/>관점 자체가 다르니까.</p></div>
272	      <div class="col">
